using System;
class OrganizationTests {
 static int checks;static void Check(bool b,string label){if(!b)throw new Exception("Organization: "+label);checks++;}
 static void Refresh(){UnityEngine.Time.unscaledTime+=31;for(int i=0;i<500;i++)NativeOrganizations.Tick();}
 public static int Run(){checks=0;World.world=new MapBox();UnityEngine.Time.unscaledTime=0;
  var c=new City();c.data.id=1001;var other=new City();other.data.id=1002;var a=new Actor{city=c};a.data.id=2001;c.units.Add(a);var b=new Actor{city=other};b.data.id=2002;other.units.Add(b);World.world.cities.list.Add(c);World.world.cities.list.Add(other);World.world.units.list.Add(a);World.world.units.list.Add(b);
  GodWorldRuntime.Issue(c,false,100);Refresh();Check(NativeOrganizations.Get(c).rank==1&&NativeOrganizations.Get(other).rank==2,"same-kind ranking uses actual wealth");Check(NativeOrganizations.Strength(c)==.15&&NativeOrganizations.Strength(other)==0,"only current leader gets automatic bonus");
  GodWorldRuntime.Issue(other,false,10000);Refresh();Check(NativeOrganizations.Strength(other)==.15&&NativeOrganizations.Strength(c)==0,"bonus transfers after leadership changes");
  Check(NativeOrganizations.Score(0,10000,99,9,99,90)==0,"empty groups cannot lead on wealth alone");Check(NativeOrganizations.Score(10,1000,30,10,20,80)>NativeOrganizations.Score(10,1000,10,0,0,20),"talent military development and stability affect score");
  NativeOrganizations.Configure(c,2,25);var culture=new Culture();a.culture=culture;NativeOrganizations.Configure(culture,2,25);Check(Math.Abs(NativeOrganizations.Bonus(a,"production")-.30)<1e-9,"overlapping organization effects capped at thirty percent");Check(NativeOrganizations.Bonus(a,"combat")==0,"city and culture bonuses do not grant combat");Check(NativeOrganizations.Scale(100,.30)==130&&NativeOrganizations.Scale(Int32.MaxValue,.30)==Int32.MaxValue,"scaled native values saturate safely");Check(NativeOrganizations.ResearchWork(a,20)==26,"research bonus reaches completed reading");
  NativeOrganizations.Configure(c,1,25);Check(NativeOrganizations.Strength(c)==0,"organization effect disable persisted");Check(NativeOrganizations.Data(culture)==culture.data,"inherited native data fields found");NativeOrganizations.Edit(c,"name",0,"新城");Check(c.data.name=="新城"&&c.data.custom_name,"organization name edited in native save data");
  var k=new Kingdom();NativeOrganizations.Edit(k,"taxLocal",37,"");NativeOrganizations.Edit(k,"taxTribute",12,"");Check(Math.Abs(NativeOrganizations.TaxLocal(k,.05f)-.37f)<.0001&&Math.Abs(NativeOrganizations.TaxTribute(k,.05f)-.12f)<.0001,"edited taxes change native return values");NativeOrganizations.Edit(k,"taxLocal",-1,"");Check(Math.Abs(NativeOrganizations.TaxLocal(k,.08f)-.08f)<.0001,"native tax mode can be restored");
  bool rejected=false;try{NativeOrganizations.Edit(k,"taxLocal",101,"");}catch{rejected=true;}Check(rejected,"invalid tax rejected");Check(NativeOrganizations.FindActor(2001)==a&&NativeOrganizations.Find(0,1001)==c,"native manager IDs resolve actual targets");
  a.data.set("god_skill_xp_2",1000000);Check(NativeProgression.Ability(a,2)==2,"legacy custom skill XP ignored in favor of native intelligence");NativeProgression.CompletedWork(a,2,3);int xp;a.data.get("god_skill_xp_2",out xp,0);Check(xp==1000000,"completed actions no longer write custom XP");
  c.alive=false;Check(NativeOrganizations.Strength(c)==0,"dead organizations lose manual effects");World.world=new MapBox();Refresh();Check(NativeOrganizations.Get(other)==null,"world reload clears ranking references");return checks;
 }
}
